package net.officefloor.hq.app.rollup;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class AuditRollup {
    // After the change's own lines: one ROLLUP per person whose figures moved (a new person counts as moved),
    // in the order they were added, then TOTALS when a sheet total moved.
    public void audit(@PathVariable("sheetId") String sheetId, @Val Figures before, Rollup rollup,
            ServerHttpConnection connection, Audit audit) {
        RollupLines.record(sheetId.trim(), Audit.user(connection), before, rollup, audit);
    }
}
package net.officefloor.hq.app.rollup;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class SnapshotRollup {
    // The sheet's figures before the change, for AuditRollup to compare with after it.
    public void snapshot(@PathVariable("sheetId") String sheetId, Rollup rollup, Out<Figures> before) {
        before.set(rollup.figures(sheetId.trim()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithEditedClaim {
    public void respond(@Val ClaimResponse claim, ObjectResponse<ClaimResponse> response) {
        response.send(claim);
    }
}
package net.officefloor.hq.app.claim;

/** A claim as the screen sees it: the amount with two decimals, the date as yyyy-MM-dd, the status by name, the number (null when it has none), the due fixed on settling (null when it has none), who opened it (null when never opened), whether its person's last statement bound it, the figure it bound (null when it has none) the number a correction corrects (null for any other claim) and the date it is due by, as yyyy-MM-dd, its status log, oldest first (empty when not listed with it), and the date it was deferred to, as yyyy-MM-dd (null when never deferred), and how many proofs it has been given, and the number of the claim it was split off (null for any other claim). */
public record ClaimResponse(long id, long personId, String amount, String date, String note, String status,
        String number, String settledDue, String openedBy, boolean stated, String statedDue,
        String corrects, String dueBy, java.util.List<String> log, String deferredUntil, int proofs,
        String splitFrom) {

    public static ClaimResponse from(Claim claim) {
        return from(claim, java.util.List.of());
    }

    public static ClaimResponse from(Claim claim, java.util.List<String> log) {
        return new ClaimResponse(claim.id(), claim.personId(), claim.amount().toPlainString(),
                claim.date().toString(), claim.note(), claim.status().name(), claim.number(),
                claim.settledDue() == null ? null : claim.settledDue().toPlainString(), claim.openedBy(), claim.stated(),
                claim.statedDue() == null ? null : claim.statedDue().toPlainString(), claim.corrects(),
                claim.dueBy().toString(), log,
                claim.deferredUntil() == null ? null : claim.deferredUntil().toString(), claim.proofs(),
                claim.splitFrom());
    }
}

